#include "coh_power_sets.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>
static unsigned long long checks,cuts,mutations;static CohPowerSetDictionary out,before;static CohPowerSetWorkspace work;
#define CHECK(x)do{checks++;if(!(x)){fprintf(stderr,"powersets%d: %s\n",__LINE__,#x);exit(1);}}while(0)
typedef struct{unsigned calls;CohStatus status;}Digest;
static CohStatus digest(void*p,CohBytes b,uint8_t h[32]){Digest*d=p;d->calls++;SHA256(b.data,b.size,h);return d->status;}
static uint32_t word(FILE*f){uint8_t b[4];CHECK(fread(b,1,4,f)==4);return(uint32_t)b[0]|(uint32_t)b[1]<<8|(uint32_t)b[2]<<16|(uint32_t)b[3]<<24;}
static CohStatus parse(CohBytes b,uint8_t h[32],CohCostumeImportDigest*d,size_t budget,size_t retained){memset(&out,0xa5,sizeof(out));before=out;CohStatus s=coh_power_sets_read(b,1,h,d,&out,&work,budget,retained);if(s!=COH_OK)CHECK(!memcmp(&out,&before,sizeof(out)));return s;}
int main(int argc,char**argv){if(argc!=2)return 2;FILE*f=fopen(argv[1],"rb");CHECK(f);unsigned cases=word(f);for(unsigned ci=0;ci<cases;ci++){unsigned size=word(f),begin=word(f);uint8_t*data=malloc(size),*changed=malloc(size);CHECK(data&&changed&&fread(data,1,size,f)==size);uint8_t hash[32];SHA256(data,size,hash);Digest context={0,COH_OK};CohCostumeImportDigest provider={digest,&context,sizeof(context),0};CHECK(parse((CohBytes){data,size},hash,&provider,COH_POWER_SET_RAM_MAX,0)==COH_OK);CHECK(context.calls==1&&out.raw_schema_validated&&out.historical_schema_crc_matched&&!out.full_power_dictionary&&!out.runtime_generation&&!out.actor_authority&&out.input.data==data&&out.input.size==size&&out.input_lease==1&&!memcmp(out.input_sha256,hash,32));CHECK(word(f)==out.count&&word(f)==out.dependency_count&&word(f)==out.power_name_count&&word(f)==out.pointer_index_count&&word(f)==out.index_slots&&word(f)==out.unique_count&&word(f)==out.duplicate_count&&word(f)==out.source_constructor_accepted);for(unsigned i=0;i<out.count;i++){CHECK(word(f)==out.entries[i].record.begin&&word(f)==out.entries[i].record.end);for(unsigned k=0;k<30;k++){uint32_t begin_field=word(f),end_field=word(f);CohBytes field={0};CHECK(coh_power_sets_field(&out,i,k,&field)==COH_OK&&field.data==data+begin_field&&field.size==end_field-begin_field);if(k==1)CHECK(begin_field==out.entries[i].full_name.begin&&end_field==out.entries[i].full_name.end);}}for(unsigned i=0;i<COH_POWER_SET_INDEX_SLOTS;i++)CHECK(word(f)==out.slots[i]);for(unsigned i=0;i<out.count;i++){unsigned n=word(f);char key[260];CHECK(n<260&&fread(key,1,n,f)==n);for(unsigned j=0;j<n;j++)if(key[j]>='A'&&key[j]<='Z')key[j]=(char)(key[j]+32);unsigned expected=word(f),index=UINT32_MAX;CHECK(coh_power_sets_find(&out,(CohBytes){(const uint8_t*)key,n},&index)==COH_OK&&index==expected);}
CohPowerSetDictionary*good=malloc(sizeof(*good));CHECK(good);*good=out;for(size_t n=1;n<size;n+=65536){context.calls=0;CHECK(parse((CohBytes){data,n},hash,&provider,COH_POWER_SET_RAM_MAX,0)!=COH_OK&&context.calls==0);cuts++;}for(size_t n=0;n<size;n+=size/31+1){memcpy(changed,data,size);changed[n]^=255;CHECK(parse((CohBytes){changed,size},hash,&provider,COH_POWER_SET_RAM_MAX,0)!=COH_OK);mutations++;}memcpy(changed,data,size);uint32_t badcount=COH_POWER_SET_MAX+1;for(unsigned i=0;i<4;i++)changed[begin+4+i]=(uint8_t)(badcount>>(8*i));uint8_t changed_hash[32];SHA256(changed,size,changed_hash);context.calls=0;CHECK(parse((CohBytes){changed,size},changed_hash,&provider,COH_POWER_SET_RAM_MAX,0)==COH_LIMIT&&!context.calls);size_t exact=sizeof(out)+sizeof(work)+sizeof(provider)+sizeof(context)+32+COH_POWER_SET_STACK_RESERVE+size;CHECK(exact<=COH_POWER_SET_RAM_MAX);CHECK(parse((CohBytes){data,size},hash,&provider,exact,0)==COH_OK);context.calls=0;CHECK(parse((CohBytes){data,size},hash,&provider,exact,1)==COH_LIMIT&&!context.calls);context.status=COH_CANCELLED;CHECK(parse((CohBytes){data,size},hash,&provider,COH_POWER_SET_RAM_MAX,0)==COH_CANCELLED);context.status=COH_OK;provider.scratch_reserve=SIZE_MAX;CHECK(parse((CohBytes){data,size},hash,&provider,COH_POWER_SET_RAM_MAX,0)==COH_LIMIT);provider.scratch_reserve=0;CHECK(coh_power_sets_read((CohBytes){data,size},1,hash,&provider,&out,(CohPowerSetWorkspace*)&out,COH_POWER_SET_RAM_MAX,0)==COH_INVALID);out=*good;uint32_t index=123;CHECK(coh_power_sets_find(&out,(CohBytes){(const uint8_t*)"Unknown_Missing_Set",19},&index)==COH_NOT_FOUND&&index==123);CHECK(coh_power_sets_find(&out,(CohBytes){(const uint8_t*)"\xff",1},&index)==COH_UNSUPPORTED);CHECK(coh_power_sets_find(&out,(CohBytes){(const uint8_t*)"x",1},&out.count)==COH_INVALID);CohBytes field={(const uint8_t*)"unchanged",9},field_before=field;CHECK(coh_power_sets_field(&out,0,30,&field)==COH_INVALID&&!memcmp(&field,&field_before,sizeof(field)));CHECK(coh_power_sets_field(&out,out.count,0,&field)==COH_STATE&&!memcmp(&field,&field_before,sizeof(field)));CHECK(coh_power_sets_field(&out,0,0,(CohBytes*)&out)==COH_INVALID);if(out.count){CohPowerSetSpan saved=out.entries[out.count-1].record;out.entries[out.count-1].record.end=UINT32_MAX;CHECK(coh_power_sets_field(&out,out.count-1,0,&field)==COH_STATE&&!memcmp(&field,&field_before,sizeof(field)));out.entries[out.count-1].record=saved;}free(good);free(changed);free(data);}CHECK(fgetc(f)==EOF);fclose(f);printf("{\"checks\":%llu,\"cases\":%u,\"cuts\":%llu,\"mutations\":%llu,\"owner_bytes\":%zu,\"full_power_dictionary\":false,\"runtime_generation\":false,\"actor_authority\":false}\n",checks,cases,cuts,mutations,sizeof(out));return 0;}
